import{_ as t,c as s,o as i,a9 as r}from"./chunks/framework.BXLNC15u.js";const h=JSON.parse('{"title":"Exports","description":"Export provider-neutral contracts for async enterprise systems.","frontmatter":{"title":"Exports","description":"Export provider-neutral contracts for async enterprise systems.","order":610060},"headers":[],"relativePath":"handbook/6_integrations/enterprise_interoperability/exports.md","filePath":"handbook/6_integrations/enterprise_interoperability/exports.md","lastUpdated":1778094759000}'),a={name:"handbook/6_integrations/enterprise_interoperability/exports.md"};function n(o,e,p,l,d,c){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to “Exports”">​</a></h1><p>Enterprise exports should be generated from declarations, not from running handlers.</p><p>Exportable declarations include:</p><ul><li>custom events and subscriptions</li><li>queues, queue workers, and result events</li><li>event-to-queue bindings</li><li>schedules</li><li>stream channels</li><li>async agent queue response contracts</li><li>runtime bridge capability reports</li></ul><p>AsyncAPI is the primary export shape for asynchronous surfaces. OpenAPI remains the primary export shape for HTTP commands, streams, and async accepted/status endpoints.</p><p>CloudEvents mapping is an interoperability adapter for external event systems. It does not replace PURISTA&#39;s internal message envelope.</p><p>Provider bindings are optional. The neutral document should be the default so teams can review ownership, schemas, idempotency strategy, and delivery limitations before choosing NATS, AMQP, MQTT, gateway, scheduler, or queue-provider details.</p><p>The billing-cycle example declares the schedule, event-to-queue binding, queue, worker, result event, and subscription in one service so these contracts can be exported without a live broker.</p><p>Use runtime capability exports next to AsyncAPI exports when reviewing operational guarantees:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">purista</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> runtime-capabilities</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> purista-runtime.json</span></span></code></pre></div><p>The capability report is intentionally truthful. For example, <code>DefaultEventBridge</code> reports no durable subscriptions and no manual ack support, while <code>DefaultQueueBridge</code> reports in-memory queue behavior and no idempotency enforcement.</p>',11)])])}const m=t(a,[["render",n]]);export{h as __pageData,m as default};
